from pathlib import Path

TARGET = Path("pages/survival_planner.py")
if not TARGET.exists():
    raise SystemExit(
        "ERROR: pages/survival_planner.py not found. "
        "Run this script from the StockPig repository root."
    )

text = TARGET.read_text(encoding="utf-8")
original = text

def replace_function(start_name: str, next_name: str, replacement: str) -> None:
    global text
    start = text.find(f"def {start_name}(")
    end = text.find(f"def {next_name}(", start)
    if start < 0 or end < 0:
        raise SystemExit(
            f"ERROR: could not locate {start_name} -> {next_name}. "
            "No changes were written."
        )
    text = text[:start] + replacement + text[end:]

replace_function(
    "build_recommended_pick_score_charts",
    "_score_distribution_svg",
    'def build_recommended_pick_score_charts(\n    probabilities: pd.DataFrame,\n    plan: list[tuple[int, tuple[int, ...]]],\n    bundle: predictor.ModelBundle,\n    planning_start_week: int,\n) -> list[dict]:\n    """Build two-team score distributions for this week\'s recommended pick(s).\n\n    Uses the same residual Monte Carlo + score_distribution path as\n    score_predictor_gpu.py.  The projected winner is labeled blue in the\n    display layer and the projected loser red.\n    """\n    selected_ids: tuple[int, ...] | None = None\n    for week, team_ids in plan:\n        if int(week) == int(planning_start_week):\n            selected_ids = tuple(int(team_id) for team_id in team_ids)\n            break\n\n    if not selected_ids:\n        return []\n\n    lookup = probabilities.set_index(["week", "team_id"], drop=False)\n    charts: list[dict] = []\n\n    for team_id in selected_ids:\n        row = lookup.loc[(int(planning_start_week), int(team_id))]\n        if isinstance(row, pd.DataFrame):\n            row = row.iloc[0]\n\n        recommended_team = str(row["team"])\n        opponent_team = str(row["opponent"])\n        recommended_win_probability = float(row["win_probability"])\n        opponent_win_probability = 1.0 - recommended_win_probability\n\n        if str(row["location"]) == "Home":\n            expected_home = float(row["expected_points"])\n            expected_away = float(row["opponent_expected_points"])\n            recommended_scores_are_home = True\n            matchup_label = f"{opponent_team} @ {recommended_team}"\n        else:\n            expected_home = float(row["opponent_expected_points"])\n            expected_away = float(row["expected_points"])\n            recommended_scores_are_home = False\n            matchup_label = f"{recommended_team} @ {opponent_team}"\n\n        game_id = int(row["game_id"])\n        home_scores, away_scores = predictor.simulate_game_from_residuals(\n            expected_home=expected_home,\n            expected_away=expected_away,\n            bundle=bundle,\n            n=int(SCORE_GRAPH_MONTE_CARLO_SIMS),\n            seed=(\n                predictor.RANDOM_SEED\n                + int(planning_start_week) * 10_007\n                + game_id % 100_000\n            ),\n        )\n\n        recommended_scores = (\n            home_scores if recommended_scores_are_home else away_scores\n        )\n        opponent_scores = (\n            away_scores if recommended_scores_are_home else home_scores\n        )\n\n        recommended_distribution = predictor.score_distribution(\n            recommended_scores\n        )\n        opponent_distribution = predictor.score_distribution(\n            opponent_scores\n        )\n\n        recommended_p10 = predictor.score_percentile(\n            recommended_scores, 10\n        )\n        recommended_p90 = predictor.score_percentile(\n            recommended_scores, 90\n        )\n        opponent_p10 = predictor.score_percentile(opponent_scores, 10)\n        opponent_p90 = predictor.score_percentile(opponent_scores, 90)\n\n        # Merge both distributions onto one score axis so Streamlit and the\n        # printable SVG use exactly the same data.\n        comparison = (\n            recommended_distribution.rename(\n                columns={"Probability": recommended_team}\n            )\n            .merge(\n                opponent_distribution.rename(\n                    columns={"Probability": opponent_team}\n                ),\n                on="Score",\n                how="outer",\n            )\n            .fillna(0.0)\n            .sort_values("Score")\n            .reset_index(drop=True)\n        )\n\n        if recommended_win_probability >= opponent_win_probability:\n            winner_team = recommended_team\n            loser_team = opponent_team\n            winner_win_probability = recommended_win_probability\n            loser_win_probability = opponent_win_probability\n            winner_expected_score = float(row["expected_points"])\n            loser_expected_score = float(row["opponent_expected_points"])\n            winner_p10 = float(recommended_p10)\n            winner_p90 = float(recommended_p90)\n            loser_p10 = float(opponent_p10)\n            loser_p90 = float(opponent_p90)\n        else:\n            winner_team = opponent_team\n            loser_team = recommended_team\n            winner_win_probability = opponent_win_probability\n            loser_win_probability = recommended_win_probability\n            winner_expected_score = float(row["opponent_expected_points"])\n            loser_expected_score = float(row["expected_points"])\n            winner_p10 = float(opponent_p10)\n            winner_p90 = float(opponent_p90)\n            loser_p10 = float(recommended_p10)\n            loser_p90 = float(recommended_p90)\n\n        charts.append(\n            {\n                "team_id": int(team_id),\n                "recommended_team": recommended_team,\n                "opponent": opponent_team,\n                "location": str(row["location"]),\n                "matchup": matchup_label,\n                "recommended_win_probability": recommended_win_probability,\n                "opponent_win_probability": opponent_win_probability,\n                "recommended_expected_score": float(row["expected_points"]),\n                "opponent_expected_score": float(\n                    row["opponent_expected_points"]\n                ),\n                "recommended_p10": float(recommended_p10),\n                "recommended_p90": float(recommended_p90),\n                "opponent_p10": float(opponent_p10),\n                "opponent_p90": float(opponent_p90),\n                "winner_team": winner_team,\n                "loser_team": loser_team,\n                "winner_win_probability": float(winner_win_probability),\n                "loser_win_probability": float(loser_win_probability),\n                "winner_expected_score": float(winner_expected_score),\n                "loser_expected_score": float(loser_expected_score),\n                "winner_p10": float(winner_p10),\n                "winner_p90": float(winner_p90),\n                "loser_p10": float(loser_p10),\n                "loser_p90": float(loser_p90),\n                "comparison_distribution": comparison,\n            }\n        )\n\n        del recommended_scores\n        del opponent_scores\n        del home_scores\n        del away_scores\n\n    gc.collect()\n    try:\n        if predictor.torch is not None and predictor.torch.cuda.is_available():\n            predictor.torch.cuda.empty_cache()\n    except Exception:\n        pass\n\n    return charts\n\n\n',
)

replace_function(
    "_score_distribution_svg",
    "_recommended_score_charts_html",
    'def _score_distribution_svg(chart: dict) -> str:\n    """Render winner (blue) and loser (red) on one print-safe SVG chart."""\n    comparison = chart["comparison_distribution"].copy()\n    if comparison.empty:\n        return "<p>No simulated score distribution is available.</p>"\n\n    winner_team = str(chart["winner_team"])\n    loser_team = str(chart["loser_team"])\n\n    comparison["Score"] = pd.to_numeric(\n        comparison["Score"], errors="coerce"\n    )\n    comparison[winner_team] = pd.to_numeric(\n        comparison[winner_team], errors="coerce"\n    )\n    comparison[loser_team] = pd.to_numeric(\n        comparison[loser_team], errors="coerce"\n    )\n    comparison = comparison.dropna().sort_values("Score")\n    if comparison.empty:\n        return "<p>No simulated score distribution is available.</p>"\n\n    scores = comparison["Score"].to_numpy(dtype=float)\n    winner_probabilities = comparison[winner_team].to_numpy(dtype=float)\n    loser_probabilities = comparison[loser_team].to_numpy(dtype=float)\n\n    width = 760.0\n    height = 270.0\n    left = 46.0\n    right = 12.0\n    top = 38.0\n    bottom = 38.0\n    plot_width = width - left - right\n    plot_height = height - top - bottom\n\n    score_min = float(scores.min())\n    score_max = float(scores.max())\n    score_span = max(score_max - score_min + 1.0, 1.0)\n    max_probability = max(\n        float(winner_probabilities.max()),\n        float(loser_probabilities.max()),\n        1e-9,\n    )\n\n    bucket_width = plot_width / score_span\n    bar_width = max(bucket_width * 0.40, 1.0)\n\n    winner_bars = []\n    loser_bars = []\n    for score, winner_probability, loser_probability in zip(\n        scores,\n        winner_probabilities,\n        loser_probabilities,\n    ):\n        center_x = (\n            left\n            + ((float(score) - score_min + 0.5) / score_span)\n            * plot_width\n        )\n\n        winner_height = (\n            float(winner_probability) / max_probability\n        ) * plot_height\n        winner_y = top + plot_height - winner_height\n        winner_bars.append(\n            f\'<rect x="{center_x - bar_width:.2f}" \'\n            f\'y="{winner_y:.2f}" width="{bar_width:.2f}" \'\n            f\'height="{winner_height:.2f}" fill="#4c78a8" \'\n            f\'fill-opacity="0.90" />\'\n        )\n\n        loser_height = (\n            float(loser_probability) / max_probability\n        ) * plot_height\n        loser_y = top + plot_height - loser_height\n        loser_bars.append(\n            f\'<rect x="{center_x:.2f}" \'\n            f\'y="{loser_y:.2f}" width="{bar_width:.2f}" \'\n            f\'height="{loser_height:.2f}" fill="#d62728" \'\n            f\'fill-opacity="0.82" />\'\n        )\n\n    tick_values = []\n    start_tick = int(math.floor(score_min / 10.0) * 10)\n    end_tick = int(math.ceil(score_max / 10.0) * 10)\n    for value in range(start_tick, end_tick + 1, 10):\n        if score_min <= value <= score_max:\n            tick_values.append(value)\n    if not tick_values:\n        tick_values = [int(round(score_min)), int(round(score_max))]\n    tick_values = sorted(set(tick_values))\n\n    x_ticks = []\n    for value in tick_values:\n        x = left + (\n            (float(value) - score_min + 0.5) / score_span\n        ) * plot_width\n        x_ticks.append(\n            f\'<line x1="{x:.2f}" y1="{top + plot_height:.2f}" \'\n            f\'x2="{x:.2f}" y2="{top + plot_height + 4:.2f}" \'\n            f\'stroke="#444" stroke-width="1" />\'\n            f\'<text x="{x:.2f}" y="{height - 12:.2f}" \'\n            f\'text-anchor="middle" font-size="11">{value}</text>\'\n        )\n\n    y_ticks = []\n    for fraction in (0.0, 0.5, 1.0):\n        probability = max_probability * fraction\n        y = top + plot_height - fraction * plot_height\n        y_ticks.append(\n            f\'<line x1="{left - 4:.2f}" y1="{y:.2f}" \'\n            f\'x2="{width - right:.2f}" y2="{y:.2f}" \'\n            f\'stroke="#ddd" stroke-width="1" />\'\n            f\'<text x="{left - 7:.2f}" y="{y + 4:.2f}" \'\n            f\'text-anchor="end" font-size="10">\'\n            f\'{100 * probability:.1f}%</text>\'\n        )\n\n    winner_label = html.escape(winner_team)\n    loser_label = html.escape(loser_team)\n    matchup = html.escape(str(chart["matchup"]))\n\n    legend = (\n        f\'<rect x="{left:.2f}" y="8" width="11" height="11" \'\n        f\'fill="#4c78a8" />\'\n        f\'<text x="{left + 16:.2f}" y="18" font-size="11">\'\n        f\'{winner_label} — projected winner \'\n        f\'({100 * float(chart["winner_win_probability"]):.1f}%)\'\n        f\'</text>\'\n        f\'<rect x="{left + 300:.2f}" y="8" width="11" height="11" \'\n        f\'fill="#d62728" />\'\n        f\'<text x="{left + 316:.2f}" y="18" font-size="11">\'\n        f\'{loser_label} — projected loser \'\n        f\'({100 * float(chart["loser_win_probability"]):.1f}%)\'\n        f\'</text>\'\n    )\n\n    return (\n        f\'<div class="score-chart-block">\'\n        f\'<h3>{matchup} simulated score distributions</h3>\'\n        f\'<p class="muted">\'\n        f\'<strong style="color:#4c78a8">{winner_label}</strong>: \'\n        f\'expected {float(chart["winner_expected_score"]):.1f}, \'\n        f\'80% range {float(chart["winner_p10"]):.0f}–\'\n        f\'{float(chart["winner_p90"]):.0f} &nbsp;|&nbsp; \'\n        f\'<strong style="color:#d62728">{loser_label}</strong>: \'\n        f\'expected {float(chart["loser_expected_score"]):.1f}, \'\n        f\'80% range {float(chart["loser_p10"]):.0f}–\'\n        f\'{float(chart["loser_p90"]):.0f}\'\n        f\'</p>\'\n        f\'<svg viewBox="0 0 {int(width)} {int(height)}" \'\n        f\'role="img" aria-label="{matchup} simulated score distributions">\'\n        + legend\n        + "".join(y_ticks)\n        + "".join(winner_bars)\n        + "".join(loser_bars)\n        + f\'<line x1="{left:.2f}" y1="{top + plot_height:.2f}" \'\n          f\'x2="{width - right:.2f}" y2="{top + plot_height:.2f}" \'\n          f\'stroke="#444" stroke-width="1" />\'\n        + "".join(x_ticks)\n        + f\'<text x="{left + plot_width / 2:.2f}" y="{height - 1:.2f}" \'\n          f\'text-anchor="middle" font-size="11">Simulated team score</text>\'\n        + "</svg></div>"\n    )\n\n\n',
)

streamlit_start_marker = '    st.markdown("#### Recommended pick score simulation")\n'
streamlit_end_marker = '    st.subheader("5. Print-friendly report")\n'
streamlit_start = text.find(streamlit_start_marker)
streamlit_end = text.find(streamlit_end_marker, streamlit_start)
if streamlit_start < 0 or streamlit_end < 0:
    raise SystemExit(
        "ERROR: could not locate the Streamlit recommended-pick chart block. "
        "No changes were written."
    )
text = (
    text[:streamlit_start]
    + '    st.markdown("#### Recommended pick score simulation")\n    score_charts = result.get("recommended_score_charts", [])\n    st.caption(\n        "Both teams use the same Monte Carlo simulation as "\n        "score_predictor_gpu.py. Blue is the model-projected winner; red is "\n        "the projected loser."\n    )\n\n    def render_score_comparison(chart: dict) -> None:\n        winner_team = chart["winner_team"]\n        loser_team = chart["loser_team"]\n\n        st.markdown(\n            f\'**{chart["matchup"]}** — \'\n            f\'🔵 {winner_team} vs 🔴 {loser_team}\'\n        )\n        st.bar_chart(\n            chart["comparison_distribution"],\n            x="Score",\n            y=[winner_team, loser_team],\n            color=["#4c78a8", "#d62728"],\n            stack=False,\n            use_container_width=True,\n        )\n        st.caption(\n            f\'🔵 {winner_team}: \'\n            f\'{100 * chart["winner_win_probability"]:.1f}% win • \'\n            f\'expected {chart["winner_expected_score"]:.1f} • \'\n            f\'80% range {chart["winner_p10"]:.0f}–\'\n            f\'{chart["winner_p90"]:.0f}  |  \'\n            f\'🔴 {loser_team}: \'\n            f\'{100 * chart["loser_win_probability"]:.1f}% win • \'\n            f\'expected {chart["loser_expected_score"]:.1f} • \'\n            f\'80% range {chart["loser_p10"]:.0f}–\'\n            f\'{chart["loser_p90"]:.0f}\'\n        )\n\n    if not score_charts:\n        st.warning("No recommended-pick score distributions are available.")\n    elif len(score_charts) == 1:\n        render_score_comparison(score_charts[0])\n    else:\n        columns = st.columns(len(score_charts))\n        for column, chart in zip(columns, score_charts):\n            with column:\n                render_score_comparison(chart)\n\n'
    + text[streamlit_end:]
)

old_report_text = "The graph(s) below use the Best Overall Survival Plan's Week\n{int(planning_start_week)} pick(s). Double-pick weeks show two graphs.\n"
new_report_text = 'Each graph compares both teams in the recommended matchup. Blue is the\nmodel-projected winner and red is the projected loser. Double-pick weeks show\ntwo matchup graphs.\n'
if old_report_text in text:
    text = text.replace(old_report_text, new_report_text, 1)

if text == original:
    raise SystemExit("ERROR: no changes were produced.")

# Validate the whole page before changing the user's working file.
compile(text, str(TARGET), "exec")

backup = TARGET.with_suffix(".py.pre_opponent_distribution_backup")
backup.write_text(original, encoding="utf-8")
TARGET.write_text(text, encoding="utf-8")

print("Updated pages/survival_planner.py")
print(f"Backup written to {backup}")
print("")
print("Recommended-pick graphs now show:")
print("  blue = model-projected winner")
print("  red  = model-projected loser")
print("  both score distributions share the same score axis")
print("  double-pick weeks still show two matchup graphs")
